def minOperations(logs):
    # Track the "depth" in directory structure
    depth = 0
    for op in logs:
        if op == "../":
            # Move up if we're not already at root
            depth = max(0, depth - 1)
        elif op == "./":
            # Stay in current directory, do nothing
            continue
        else:
            # Move into subdirectory
            depth += 1
    return depth
